/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, a=0;
  wire match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .a(a), .match(match));
  always #5 clk = ~clk;

  task drive(input bit v);
    begin
      a = v;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b a_tem=%09b match=%0b mf=%0b mb=%0b", $time, a, dut.a_tem, match, dut.match_f, dut.match_b);
    end
  endtask

  initial begin
    repeat(2) @(posedge clk);
    rst_n = 1;
    // drive 011000110, should match after 9th bit
    drive(0); drive(1); drive(1); drive(0); drive(0); drive(0); drive(1); drive(1); drive(0);
    drive(1);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

